ON CONFLICT (story_id, episode_number) DO UPDATE SET
    title = EXCLUDED.title,
    content = EXCLUDED.content,
    is_free = EXCLUDED.is_free,
    price = EXCLUDED.price;

-- 4. Vérification du résultat
SELECT count(*) as total_stories FROM public.stories;
SELECT episode_number, title, is_free, price, length(content) as content_length 
FROM public.episodes 
WHERE story_id = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890'
ORDER BY episode_number ASC;
